const root=$input.first().json||{};
const src=root.error || root.input?.error || root.input || root;
const code=String(src.code||src.error_code||'').toLowerCase();
const msg=String(src.message||src.error_message||'').toLowerCase();
const status=Number(src.status_code||src.status||0)||null;
const hay=`${code} ${msg}`;
let pattern={id:'unknown',category:'unknown',retryable:false,likely_causes:['Unclassified provider or workflow failure'],remediations:['Inspect the raw error and upstream payload','Reproduce with a minimal test case','Route unresolved cases to manual review']};
const set=(id,category,retryable,causes,fixes)=>pattern={id,category,retryable,likely_causes:causes,remediations:fixes};
if(status===401 || /unauth|invalid token|expired token|credential/.test(hay)) set('auth_invalid_or_expired','authentication',false,['Missing/expired/incorrect credential','Wrong auth scheme'],['Re-authenticate or rotate the credential','Confirm Authorization/header format','Run C6-C and C6-C1']);
else if(status===403 || /forbidden|scope|permission|access denied/.test(hay)) set('auth_scope_or_permission','authorization',false,['Credential is valid but lacks scope/role/access'],['Compare required scopes to granted scopes','Confirm resource ownership/tenant','Run provider access test']);
else if(status===429 || /rate.?limit|too many requests/.test(hay)) set('rate_limit','provider_throttling',true,['Provider rate limit exceeded','Burst concurrency too high'],['Honor Retry-After','Back off exponentially','Queue/retry through C6-G']);
else if(status===408 || /timeout|timed out|etimedout/.test(hay)) set('timeout','network_or_provider',true,['Provider response exceeded timeout','Network instability'],['Increase bounded timeout only if justified','Retry with backoff','Reduce payload/work per request']);
else if(status===404 || /not found/.test(hay)) set('not_found','resource',false,['Wrong endpoint/resource ID','Resource deleted or inaccessible'],['Verify URL and resource identifiers','Check environment/tenant']);
else if(status===409 || /duplicate|conflict|already exists/.test(hay)) set('duplicate_or_conflict','data_state',false,['Duplicate record or state conflict'],['Use dedupe/idempotency check','Switch create to update/upsert where appropriate']);
else if(status===400 || /schema|mapping|invalid field|required field|validation/.test(hay)) set('validation_or_mapping','data_contract',false,['Payload does not match provider schema','Required/type-mismatched field'],['Run C6-D','Compare request to provider schema','Normalize data before provider call']);
else if(status && status>=500) set('provider_5xx','provider',true,['Provider/server failure'],['Retry with bounded backoff','Log incident','Escalate after retry budget']);
else if(/dns|enotfound|econnreset|econnrefused|network/.test(hay)) set('network_connectivity','network',true,['DNS/network/socket failure'],['Verify host/network','Retry with backoff','Check firewall/proxy']);
return [{json:{success:true,component_id:'C6-B',component_version:'v1',source_error:{code:src.code||src.error_code||null,message:src.message||src.error_message||null,status_code:status},pattern,next_action:pattern.retryable?'prepare_retry_policy':'apply_remediation_or_manual_review',error:null}}];
